// The Worker's entry (wrangler.toml main): the host rules first, then OpenNext's worker.
// www.<SHEPETAL_DOMAIN> goes to the apex; the old host (shepetal.backant.io) moves every path, /api/* included, to the
// domain with a 301 (src/lib/site.ts). Static files (the assets binding) are served before this runs.
import { analyticsConfig } from './src/lib/analytics-config';
import { hostRedirect } from './src/lib/site';
// @ts-ignore: generated by `opennextjs-cloudflare build` (absent before the first build), resolved by wrangler
import openNext from './.open-next/worker.js';

// @ts-ignore: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';

type Env = { POSTHOG_KEY?: string; POSTHOG_HOST?: string };

export default {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const moved = hostRedirect(new URL(request.url));
    if (moved) return moved;
    const res: Response = await openNext.fetch(request, env, ctx);
    return withAnalytics(res, env);
  },
};

/**
 * With POSTHOG_KEY set (a secret, set at GO), every HTML page gets <meta name="shepetal-analytics"> with the key and
 * host, which src/components/Analytics.tsx reads. Without it, pages are passed through untouched and no analytics
 * code ever loads. Pages stay static: the key is added here, at the edge, not baked into the build.
 */
function withAnalytics(res: Response, env: Env): Response {
  const { key, host } = analyticsConfig(env);
  if (!key || !(res.headers.get('content-type') ?? '').startsWith('text/html')) return res;
  const content = JSON.stringify({ key, host }).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
  return new HTMLRewriter()
    .on('head', {
      element: (head) => {
        head.append(`<meta name="shepetal-analytics" content="${content}">`, { html: true });
      },
    })
    .transform(res);
}
